+
+import "testing"
+
+func TestTotal(t *testing.T) {
+	lines := []Line{{PriceCents: 1500, Qty: 2}, {PriceCents: 250, Qty: 4}}
+	if got := Total(lines, 500); got != 3500 {
+		t.Fatalf("Total = %d, want 3500", got)
+	}
